import assert from 'node:assert/strict';
import {create,isFieldSet,mergeFromBinary,fromBinary,toBinary} from '@bufbuild/protobuf';
import {anyPack,anyUnpack} from '@bufbuild/protobuf/wkt';
import {ScalarsCreate,ScalarsSchema,ScalarsBinary,ScalarsJson,NodeCreate,NodeSchema,NodeBinary,WellKnownCreate,WellKnownBinary,WellKnownJson} from './dist/wire.js';
import {registry} from './dist/poolster-rpc-runtime.js';
const extremes=ScalarsCreate({int32Value:-2147483648,uint32Value:4294967295,sint32Value:-2147483648,fixed32Value:4294967295,sfixed32Value:2147483647,int64Value:-9223372036854775808n,uint64Value:18446744073709551615n,sint64Value:9223372036854775807n,fixed64Value:18446744073709551615n,sfixed64Value:-9223372036854775808n,doubleValue:Infinity,floatValue:NaN,boolValue:true,stringValue:'héllo',bytesValue:Uint8Array.from([0,255]),optionalValue:0,alternative:{case:'integer',value:0},packedValues:[0,1,-1],unpackedValues:[4,5],wideKeys:{'9223372036854775807':'max'},nodes:{first:NodeCreate({name:'a'})},kind:987,node:NodeCreate({name:'root',child:{name:'nested'}})});
const bytes=ScalarsBinary.encode(extremes);assert.deepEqual(ScalarsBinary.decode(bytes),extremes);assert.equal(isFieldSet(extremes,ScalarsSchema.field.optionalValue),true);
assert.equal(isFieldSet(ScalarsCreate(),ScalarsSchema.field.optionalValue),false);
const json=JSON.parse(ScalarsJson.stringify(extremes));assert.equal(json.customString,'héllo');assert.equal(json.int64Value,'-9223372036854775808');assert.equal(json.uint64Value,'18446744073709551615');assert.equal(json.bytesValue,'AP8=');assert.equal(json.doubleValue,'Infinity');assert.equal(json.floatValue,'NaN');assert.equal(json.kind,987);
assert.deepEqual(ScalarsJson.parse(JSON.stringify(json)),extremes);
assert.equal(ScalarsJson.parse('{"string_value":"original-name"}').stringValue,'original-name');
assert.equal(ScalarsJson.parse('{"customString":"custom-name"}').stringValue,'custom-name');
assert.throws(()=>ScalarsJson.parse('{"unknown":1}'),/unknown|cannot decode/i);
assert.equal(ScalarsJson.parse('{"unknown":1}',{ignoreUnknownFields:true}).int32Value,0);
for(const duplicate of ['{"int32Value":1,"int32Value":2}','{"int32Value":1,"int32_value":2}','{"text":"one","integer":2}'])assert.throws(()=>ScalarsJson.parse(duplicate));
assert.equal(ScalarsJson.parse('{"optionalValue":null}').optionalValue,undefined);
assert.equal(JSON.parse(ScalarsJson.stringify(ScalarsCreate(),{alwaysEmitImplicit:true})).int32Value,0);
assert.equal(JSON.parse(ScalarsJson.stringify(ScalarsCreate({kind:1}),{enumAsInteger:true})).kind,1);
assert.equal(ScalarsJson.parse('{"kind":"FIRST_ALIAS"}').kind,1);
for(const value of [{uint32Value:-1},{uint32Value:4294967296},{int32Value:1.5},{int64Value:9223372036854775808n},{uint64Value:-1n}])assert.throws(()=>ScalarsBinary.encode(ScalarsCreate(value)));
for(const invalid of [[8],[10,4,1],[0],[15,0],[0xff,0xff,0xff,0xff,0xff,0xff,0xff,0xff,0xff,0xff,2]])assert.throws(()=>ScalarsBinary.decode(Uint8Array.from(invalid)));
assert.throws(()=>ScalarsBinary.decode(new Uint8Array(4097)),/exceeds.*bytes/);
let deep=NodeCreate();for(let i=0;i<10;i++)deep=NodeCreate({child:deep});assert.throws(()=>NodeBinary.encode(deep),/depth/);
const cycle=NodeCreate();cycle.child=cycle;assert.throws(()=>NodeBinary.encode(cycle),/cycle/);
const first=ScalarsCreate();const second=ScalarsCreate();first.packedValues.push(1);first.nodes.a=NodeCreate();assert.equal(second.packedValues.length,0);assert.deepEqual(Object.keys(second.nodes),[]);
const merged=ScalarsCreate({packedValues:[1],nodes:{a:NodeCreate({name:'a'})}});mergeFromBinary(ScalarsSchema,merged,ScalarsBinary.encode(ScalarsCreate({packedValues:[2],nodes:{b:NodeCreate({name:'b'})}})));assert.deepEqual(merged.packedValues,[1,2]);assert.deepEqual(Object.keys(merged.nodes).sort(),['a','b']);
// Future field 100 survives old-schema decoding and re-encoding.
const unknown=Uint8Array.from([0xa0,0x06,0x07]);assert.deepEqual(ScalarsBinary.encode(ScalarsBinary.decode(unknown)),unknown);
// Independent manually encoded wire vectors: packed and unpacked accepted for either declaration; last oneof wins.
assert.deepEqual(ScalarsBinary.decode(Uint8Array.from([0x98,0x01,1,0x98,0x01,2])).packedValues,[1,2]);
assert.deepEqual(ScalarsBinary.decode(Uint8Array.from([0xa2,0x01,2,1,2])).unpackedValues,[1,2]);
assert.deepEqual(ScalarsBinary.decode(Uint8Array.from([0x8a,0x01,1,0x61,0x90,0x01,3])).alternative,{case:'integer',value:3});
const any=anyPack(NodeSchema,NodeCreate({name:'embedded'}));assert.equal(anyUnpack(any,NodeSchema).name,'embedded');
const wk=WellKnownJson.parse('{"timestamp":"2000-01-01T01:00:00.123456789+01:00","duration":"-1.000000001s","wideWrapper":"9007199254740993","boolWrapper":false,"empty":{},"any":{"@type":"type.googleapis.com/conformance.Node","name":"embedded"},"object":{"nested":[1,true,null]},"value":"text","list":[1,"a",null],"mask":"fooBar,nested.child"}');
const rendered=JSON.parse(WellKnownJson.stringify(wk));assert.equal(rendered.timestamp,'2000-01-01T00:00:00.123456789Z');assert.equal(rendered.duration,'-1.000000001s');assert.equal(rendered.wideWrapper,'9007199254740993');assert.equal(rendered.boolWrapper,false);assert.equal(rendered.mask,'fooBar,nested.child');assert.deepEqual(WellKnownBinary.decode(WellKnownBinary.encode(wk)),wk);
assert.equal(WellKnownCreate().boolWrapper,undefined);assert.ok(registry.getMessage('conformance.Node'));
console.log('wire JSON WKT conformance passed');
const representationModule=await import('./dist/wire.js');
const representation=representationModule.RepresentationCreate({text:'9007199254740993',texts:['18446744073709551615'],numeric:9007199254740993n,choice:{case:'key',value:'-9007199254740993'}});
assert.equal(typeof representation.text,'string');assert.equal(typeof representation.numeric,'bigint');assert.deepEqual(representationModule.RepresentationBinary.decode(representationModule.RepresentationBinary.encode(representation)),representation);assert.deepEqual(representationModule.RepresentationJson.parse(representationModule.RepresentationJson.stringify(representation)),representation);
